function power(a, b) {
    let ans = 1n;
    if (b === 0n) return 1n;
    while (b > 0n) {
        if (b % 2n !== 0n) ans = ans * a;
        a = a * a;
        b = b / 2n;
    }
    return ans;
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) return;
    let n = BigInt(input);
    let index = 0n;
    let i = 0n;

    while (n > 0n) {
        const rem = n % 10n;
        if (rem === 4n) {
            index += power(2n, i);
        } else {
            index += power(2n, i + 1n);
        }
        n = n / 10n;
        i++;
    }
    console.log(index.toString());
}

main();

